@@ -0,0 +1,332 @@
+// Classifies one full, unfiltered Trivy JSON report (--pkg-types os, with no
+// result-filtering flags at all) into blocking vs. reporting buckets under
+// the OS-scan policy (docs/os-scan-policy.md, D-08..D-12). Node stdlib only:
+// fs is required lazily inside the CLI's default IO so the pure
+// classification functions stay dependency-free, in the same style as
+// ci-job-consistency.cjs.
+
+const REQUIRED_EXCEPTION_FIELDS = ['id', 'package', 'reason', 'approved_by', 'approved_on'];
+const STRICT_DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
+const MS_PER_DAY = 24 * 60 * 60 * 1000;
+
+// Parses a strict YYYY-MM-DD string to a UTC millisecond timestamp, rejecting
+// any string that doesn't round-trip exactly (catches e.g. "2026-13-40",
+// which Date.UTC would otherwise silently roll over into a different date).
+function parseStrictDateUTC(value) {
+  if (typeof value !== 'string' || !STRICT_DATE_RE.test(value)) return null;
+  const [year, month, day] = value.split('-').map(Number);
+  const ms = Date.UTC(year, month - 1, day);
+  const roundTrip = new Date(ms);
+  if (roundTrip.getUTCFullYear() !== year || roundTrip.getUTCMonth() !== month - 1 || roundTrip.getUTCDate() !== day) {
+    return null;
+  }
+  return ms;
+}
+
+// Parses + structurally validates a Trivy JSON report, throwing a
+// "scanner error: ..." message for every failure mode so the caller can
+// fail the job closed rather than silently treating a hollow scan as clean
+// (D-12, T-85-20).
+function parseReport(text) {
+  let parsed;
+  try {
+    parsed = JSON.parse(text);
+  } catch {
+    throw new Error('scanner error: report is not valid JSON');
+  }
+  if (!parsed || parsed.SchemaVersion !== 2) {
+    throw new Error('scanner error: unsupported SchemaVersion');
+  }
+  if (!Array.isArray(parsed.Results)) {
+    throw new Error('scanner error: report has no Results');
+  }
+  const hasOsPkgs = parsed.Results.some(result => result && result.Class === 'os-pkgs');
+  if (!hasOsPkgs) {
+    throw new Error('scanner error: no OS-package result');
+  }
+  const family = parsed.Metadata && parsed.Metadata.OS && parsed.Metadata.OS.Family;
+  if (typeof family !== 'string' || family.trim() === '') {
+    throw new Error('scanner error: image OS was not detected');
+  }
+  return parsed;
+}
+
+// Validates the custom exceptions register (schema 1) against D-10: every
+// entry needs id/package/reason/approved_by/approved_on/expires, approved_on
+// can't be in the future, and expires must be within 30 days of both
+// approved_on and today. A well-formed but now-past-expiry entry is not an
+// error -- it moves to the `expired` bucket so classifyFindings re-blocks its
+// finding instead of the whole file failing closed.
+function validateExceptions(parsed, today) {
+  if (!parsed || parsed.schema !== 1 || !Array.isArray(parsed.exceptions)) {
+    throw new Error('exceptions file: schema must be 1 with an "exceptions" array');
+  }
+  const todayMs = parseStrictDateUTC(today);
+  if (todayMs === null) {
+    throw new Error(`exceptions file: invalid date for "today": ${JSON.stringify(today)}`);
+  }
+
+  const valid = [];
+  const expired = [];
+  for (const entry of parsed.exceptions) {
+    const id = (entry && entry.id) || '?';
+    for (const field of REQUIRED_EXCEPTION_FIELDS) {
+      if (!entry || !entry[field]) {
+        throw new Error(`exceptions file: ${id}: missing required field "${field}"`);
+      }
+    }
+    if (!entry.expires) {
+      throw new Error(`exceptions file: ${id}: no expiry`);
+    }
+
+    const approvedMs = parseStrictDateUTC(entry.approved_on);
+    if (approvedMs === null) {
+      throw new Error(`exceptions file: ${id}: invalid date in "approved_on"`);
+    }
+    const expiresMs = parseStrictDateUTC(entry.expires);
+    if (expiresMs === null) {
+      throw new Error(`exceptions file: ${id}: invalid date in "expires"`);
+    }
+
+    if (approvedMs > todayMs) {
+      throw new Error(`exceptions file: ${id}: approved_on is in the future`);
+    }
+
+    const daysFromApproval = (expiresMs - approvedMs) / MS_PER_DAY;
+    if (daysFromApproval > 30) {
+      throw new Error(`exceptions file: ${id}: expires more than 30 days after approved_on`);
+    }
+    const daysFromToday = (expiresMs - todayMs) / MS_PER_DAY;
+    if (daysFromToday > 30) {
+      throw new Error(`exceptions file: ${id}: expires more than 30 days after today`);
+    }
+
+    if (expiresMs < todayMs) {
+      expired.push(entry);
+    } else {
+      valid.push(entry);
+    }
+  }
+  return {valid, expired};
+}
+
+function hasFixAvailable(vuln) {
+  return typeof vuln.FixedVersion === 'string' && vuln.FixedVersion.trim() !== '';
+}
+
+function isBlockingSeverity(severity) {
+  const upper = (severity || '').toUpperCase();
+  return upper === 'CRITICAL' || upper === 'HIGH';
+}
+
+function findMatchingException(entries, id, pkg) {
+  return entries.find(entry => entry.id === id && entry.package === pkg);
+}
+
+// Classifies every finding in the report into exactly one bucket. Never
+// filters a result before classifying it (a status-filtering Trivy flag
+// would silently drop unfixed Critical/High findings, violating D-09) --
+// every finding from every Results entry lands somewhere.
+function classifyFindings({report, exceptions, today}) {
+  const blocking = [];
+  const excepted = [];
+  const expiredExceptions = [];
+  const reportedUnfixed = [];
+  const reportedOther = [];
+  const ignoredNonOs = [];
+
+  const validExceptions = (exceptions && exceptions.valid) || [];
+  const expiredEntries = (exceptions && exceptions.expired) || [];
+
+  for (const result of report.Results || []) {
+    const vulnerabilities = result.Vulnerabilities || [];
+    for (const vuln of vulnerabilities) {
+      const entry = {
+        id: vuln.VulnerabilityID,
+        package: vuln.PkgName,
+        installed: vuln.InstalledVersion,
+        fixed: typeof vuln.FixedVersion === 'string' ? vuln.FixedVersion : '',
+        severity: (vuln.Severity || 'UNKNOWN').toUpperCase(),
+      };
+
+      if (result.Class !== 'os-pkgs') {
+        ignoredNonOs.push(entry);
+        continue;
+      }
+
+      const blockingSeverity = isBlockingSeverity(entry.severity);
+      const fixed = hasFixAvailable(vuln);
+
+      if (!blockingSeverity) {
+        reportedOther.push(entry);
+        continue;
+      }
+      if (!fixed) {
+        reportedUnfixed.push(entry);
+        continue;
+      }
+
+      const validMatch = findMatchingException(validExceptions, entry.id, entry.package);
+      if (validMatch) {
+        excepted.push({...entry, expires: validMatch.expires});
+        continue;
+      }
+
+      const expiredMatch = findMatchingException(expiredEntries, entry.id, entry.package);
+      if (expiredMatch) {
+        expiredExceptions.push(entry.id);
+      }
+      blocking.push(entry);
+    }
+  }
+
+  return {blocking, excepted, expiredExceptions, reportedUnfixed, reportedOther, ignoredNonOs};
+}
+
+function renderTable(lines, label, entries, withExpiry) {
+  if (!entries.length) return;
+  lines.push(`### ${label}`);
+  lines.push('');
+  lines.push(
+    withExpiry
+      ? '| ID | Package | Installed | Fixed | Severity | Exception expiry |'
+      : '| ID | Package | Installed | Fixed | Severity |'
+  );
+  lines.push(withExpiry ? '|----|---------|-----------|-------|----------|-------------------|' : '|----|---------|-----------|-------|----------|');
+  for (const entry of entries) {
+    const row = [entry.id, entry.package, entry.installed, entry.fixed || '(none)', entry.severity];
+    if (withExpiry) row.push(entry.expires || '');
+    lines.push(`| ${row.join(' | ')} |`);
+  }
+  lines.push('');
+}
+
+// Renders the full classification result as markdown. Every bucket gets its
+// own section (when non-empty) so nothing found by the scan is ever hidden
+// from reviewers, even a blocked run's unfixed/other/ignored findings
+// (T-85-22).
+function renderSummary(result, {today, trivyVersion} = {}) {
+  const lines = [];
+  lines.push('## OS-package scan');
+  lines.push('');
+  if (today || trivyVersion) {
+    lines.push(`Scanned: ${today || 'unknown date'}${trivyVersion ? ` (Trivy ${trivyVersion})` : ''}`);
+    lines.push('');
+  }
+  lines.push(
+    [
+      `blocking: ${result.blocking.length}`,
+      `excepted: ${result.excepted.length}`,
+      `expired exceptions: ${result.expiredExceptions.length}`,
+      `reported unfixed: ${result.reportedUnfixed.length}`,
+      `reported other: ${result.reportedOther.length}`,
+      `ignored non-OS: ${result.ignoredNonOs.length}`,
+    ].join(', ')
+  );
+  lines.push('');
+
+  renderTable(lines, 'Blocking', result.blocking, false);
+  renderTable(lines, 'Excepted', result.excepted, true);
+  if (result.expiredExceptions.length) {
+    lines.push('### Expired exceptions (no longer suppressing; finding now blocks)');
+    lines.push('');
+    lines.push(result.expiredExceptions.join(', '));
+    lines.push('');
+  }
+  renderTable(lines, 'Reported (unfixed)', result.reportedUnfixed, false);
+  renderTable(lines, 'Reported (other)', result.reportedOther, false);
+  renderTable(lines, 'Ignored (non-OS)', result.ignoredNonOs, false);
+
+  lines.push('Policy: docs/os-scan-policy.md');
+  return lines.join('\n');
+}
+
+function parseArgs(argv) {
+  const args = {};
+  for (let i = 0; i < argv.length; i++) {
+    const token = argv[i];
+    if (token.startsWith('--')) {
+      args[token.slice(2)] = argv[i + 1];
+      i++;
+    }
+  }
+  return args;
+}
+
+function defaultIo() {
+  const fs = require('node:fs');
+  return {
+    readFile: path => fs.readFileSync(path, 'utf8'),
+    writeSummary: (path, content) => {
+      if (path) fs.writeFileSync(path, content);
+    },
+    stderr: message => {
+      process.stderr.write(`${message}\n`);
+    },
+  };
+}
+
+// CLI entry point: --report <path> --exceptions <path> [--today YYYY-MM-DD]
+// [--summary <path>] [--trivy-version <v>]. Writes the summary before
+// returning so a blocked run still shows everything it found, then exits 1
+// for a non-empty blocking bucket, a scanner error, or an invalid exceptions
+// file -- 0 otherwise.
+function runCli(argv, io = defaultIo()) {
+  const args = parseArgs(argv);
+  const today = args.today || new Date().toISOString().slice(0, 10);
+
+  let reportText;
+  let exceptionsText;
+  try {
+    reportText = io.readFile(args.report);
+  } catch (err) {
+    io.stderr(`OS-package scan: failed to read report file: ${err.message}`);
+    return 1;
+  }
+  try {
+    exceptionsText = io.readFile(args.exceptions);
+  } catch (err) {
+    io.stderr(`OS-package scan: failed to read exceptions file: ${err.message}`);
+    return 1;
+  }
+
+  let report;
+  try {
+    report = parseReport(reportText);
+  } catch (err) {
+    io.stderr(`OS-package scan: ${err.message}`);
+    return 1;
+  }
+
+  let exceptionsParsed;
+  try {
+    exceptionsParsed = JSON.parse(exceptionsText);
+  } catch {
+    io.stderr('OS-package scan: exceptions file: report is not valid JSON');
+    return 1;
+  }
+
+  let validated;
+  try {
+    validated = validateExceptions(exceptionsParsed, today);
+  } catch (err) {
+    io.stderr(`OS-package scan: ${err.message}`);
+    return 1;
+  }
+
+  const result = classifyFindings({report, exceptions: validated, today});
+  const summary = renderSummary(result, {today, trivyVersion: args['trivy-version']});
+  io.writeSummary(args.summary, summary);
+
+  if (result.blocking.length > 0) {
+    io.stderr(`OS-package scan: ${result.blocking.length} blocking finding(s)`);
+    return 1;
+  }
+  return 0;
+}
+
+if (require.main === module) {
+  process.exitCode = runCli(process.argv.slice(2));
+}
+
+module.exports = {parseReport, validateExceptions, classifyFindings, renderSummary, runCli};
diff --git a/.github/scripts/os-scan-gate.test.cjs b/.github/scripts/os-scan-gate.test.cjs
new file mode 100644
index 0000000..c3f4b3b
--- /dev/null
+++ b/.github/scripts/os-scan-gate.test.cjs
@@ -0,0 +1,301 @@
+const {test} = require('node:test');
+const assert = require('node:assert/strict');
+const {parseReport, validateExceptions, classifyFindings, renderSummary, runCli} = require('./os-scan-gate.cjs');
+
+// Fixed "today" for every call -- never Date.now() in these tests (D-10 math must be deterministic).
+const TODAY = '2026-10-26';
+
+// Small inline report builders (per plan action: report({vulns, os, extraResults})).
+function vuln(overrides = {}) {
+  return {
+    VulnerabilityID: 'CVE-2026-0001',
+    PkgName: 'openssl',
+    InstalledVersion: '3.0.1',
+    FixedVersion: '3.0.2',
+    Severity: 'HIGH',
+    Status: 'fixed',
+    Title: 'Example vulnerability',
+    ...overrides,
+  };
+}
+
+function report({vulns = [], os = 'debian', extraResults = []} = {}) {
+  return {
+    SchemaVersion: 2,
+    Metadata: {OS: {Family: os, Name: '13.1'}},
+    Results: [
+      {Target: 'rootfs', Class: 'os-pkgs', Type: os, Vulnerabilities: vulns},
+      ...extraResults,
+    ],
+  };
+}
+
+function exceptionEntry(overrides = {}) {
+  return {
+    id: 'CVE-2026-0001',
+    package: 'openssl',
+    reason: 'Base image rebuild scheduled next monthly cycle.',
+    approved_by: 'thejuran',
+    approved_on: '2026-10-20',
+    expires: '2026-11-15',
+    ...overrides,
+  };
+}
+
+function exceptionsFile(entries = []) {
+  return {schema: 1, exceptions: entries};
+}
+
+const NO_EXCEPTIONS = {valid: [], expired: []};
+
+// --- classifyFindings: severity/fix classification ---------------------------------------
+
+test('HIGH with a fix blocks, naming the CVE, package, installed and fixed versions', () => {
+  const r = report({vulns: [vuln({Severity: 'HIGH', FixedVersion: '3.0.2'})]});
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 1);
+  const entry = result.blocking[0];
+  assert.equal(entry.id, 'CVE-2026-0001');
+  assert.equal(entry.package, 'openssl');
+  assert.equal(entry.installed, '3.0.1');
+  assert.equal(entry.fixed, '3.0.2');
+});
+
+test('CRITICAL with no fix available is not blocking; it is reportedUnfixed', () => {
+  const r = report({vulns: [vuln({Severity: 'CRITICAL', FixedVersion: ''})]});
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 0);
+  assert.equal(result.reportedUnfixed.length, 1);
+  assert.equal(result.reportedUnfixed[0].id, 'CVE-2026-0001');
+});
+
+test('MEDIUM with a fix is not blocking; it is reportedOther', () => {
+  const r = report({vulns: [vuln({Severity: 'MEDIUM', FixedVersion: '1.2.3'})]});
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 0);
+  assert.equal(result.reportedOther.length, 1);
+});
+
+test('a lang-pkgs result with a CRITICAL fixable finding is ignored, never blocking', () => {
+  const r = report({
+    vulns: [],
+    extraResults: [
+      {
+        Target: 'app/requirements.txt',
+        Class: 'lang-pkgs',
+        Type: 'python-pkg',
+        Vulnerabilities: [vuln({VulnerabilityID: 'CVE-2026-LANG', Severity: 'CRITICAL', FixedVersion: '9.9.9'})],
+      },
+    ],
+  });
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 0);
+  assert.equal(result.ignoredNonOs.length, 1);
+  assert.equal(result.ignoredNonOs[0].id, 'CVE-2026-LANG');
+});
+
+test('unknown severity strings are never dropped; they land in reportedOther', () => {
+  const r = report({vulns: [vuln({Severity: 'weird-value', FixedVersion: '1.0.0'})]});
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 0);
+  assert.equal(result.reportedOther.length, 1);
+});
+
+test('severity comparison is case-insensitive', () => {
+  const r = report({vulns: [vuln({Severity: 'high', FixedVersion: '3.0.2'})]});
+  const result = classifyFindings({report: r, exceptions: NO_EXCEPTIONS, today: TODAY});
+  assert.equal(result.blocking.length, 1);
+});
+
+// --- classifyFindings: exception matching -------------------------------------------------
+
+test('a valid exception matching id+package excepts the finding and records its expiry', () => {
+  const r = report({vulns: [vuln({Severity: 'HIGH', FixedVersion: '3.0.2'})]});
+  const exception = exceptionEntry({approved_on: '2026-10-20', expires: '2026-11-15'});
+  const result = classifyFindings({report: r, exceptions: {valid: [exception], expired: []}, today: TODAY});
+  assert.equal(result.blocking.length, 0);
+  assert.equal(result.excepted.length, 1);
+  assert.equal(result.excepted[0].id, 'CVE-2026-0001');
+  assert.equal(result.excepted[0].expires, '2026-11-15');
+});
+
+test('an exception for the same id but a different package does not except the finding', () => {
+  const r = report({vulns: [vuln({Severity: 'HIGH', FixedVersion: '3.0.2'})]});
+  const exception = exceptionEntry({package: 'curl'});
+  const result = classifyFindings({report: r, exceptions: {valid: [exception], expired: []}, today: TODAY});
+  assert.equal(result.blocking.length, 1);
+  assert.equal(result.excepted.length, 0);
+});
+
+test('an expired exception stops suppressing: the finding blocks again and the id is listed as expired', () => {
+  const r = report({vulns: [vuln({Severity: 'HIGH', FixedVersion: '3.0.2'})]});
+  const exceptionsParsed = exceptionsFile([exceptionEntry({approved_on: '2026-09-26', expires: '2026-10-25'})]);
+  const {valid, expired} = validateExceptions(exceptionsParsed, TODAY);
+  assert.equal(valid.length, 0);
+  assert.equal(expired.length, 1);
+  const result = classifyFindings({report: r, exceptions: {valid, expired}, today: TODAY});
+  assert.equal(result.blocking.length, 1);
+  assert.deepEqual(result.expiredExceptions, ['CVE-2026-0001']);
+});
+
+// --- validateExceptions: structural and date validation (fails closed) --------------------
+
+test('expires missing throws "no expiry"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({expires: undefined})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /no expiry/);
+});
+
+test('expires more than 30 days after approved_on throws "more than 30 days"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({approved_on: '2026-09-25', expires: '2026-10-26'})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /more than 30 days/);
+});
+
+test('expires more than 30 days after today throws "more than 30 days" even though approved_on is recent', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({approved_on: '2026-10-26', expires: '2026-12-10'})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /more than 30 days/);
+});
+
+test('approved_on after today throws "approved_on is in the future"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({approved_on: '2026-10-27', expires: '2026-11-10'})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /approved_on is in the future/);
+});
+
+test('missing reason throws "missing required field"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({reason: undefined})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /missing required field/);
+});
+
+test('missing approved_by throws "missing required field"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({approved_by: undefined})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /missing required field/);
+});
+
+test('schema other than 1 throws "exceptions file"', () => {
+  assert.throws(() => validateExceptions({schema: 2, exceptions: []}, TODAY), /exceptions file/);
+});
+
+test('exceptions not an array throws "exceptions file"', () => {
+  assert.throws(() => validateExceptions({schema: 1, exceptions: {}}, TODAY), /exceptions file/);
+});
+
+test('an invalid date string throws "invalid date"', () => {
+  const exceptionsParsed = exceptionsFile([exceptionEntry({expires: '2026-13-40'})]);
+  assert.throws(() => validateExceptions(exceptionsParsed, TODAY), /invalid date/);
+});
+
+// --- parseReport: scanner errors fail closed (D-12) ----------------------------------------
+
+test('non-JSON report text fails closed with "report is not valid JSON"', () => {
+  assert.throws(() => parseReport('this is not json'), /scanner error: report is not valid JSON/);
+});
+
+test('SchemaVersion other than 2 fails closed with "unsupported SchemaVersion"', () => {
+  const bad = JSON.stringify({
+    SchemaVersion: 1,
+    Metadata: {OS: {Family: 'debian'}},
+    Results: [{Class: 'os-pkgs', Vulnerabilities: []}],
+  });
+  assert.throws(() => parseReport(bad), /scanner error: unsupported SchemaVersion/);
+});
+
+test('a missing Results array fails closed with "report has no Results"', () => {
+  const bad = JSON.stringify({SchemaVersion: 2, Metadata: {OS: {Family: 'debian'}}});
+  assert.throws(() => parseReport(bad), /scanner error: report has no Results/);
+});
+
+test('Results with no os-pkgs entry fails closed with "no OS-package result"', () => {
+  const bad = JSON.stringify({
+    SchemaVersion: 2,
+    Metadata: {OS: {Family: 'debian'}},
+    Results: [{Class: 'lang-pkgs', Vulnerabilities: []}],
+  });
+  assert.throws(() => parseReport(bad), /scanner error: no OS-package result/);
+});
+
+test('missing Metadata.OS.Family fails closed with "image OS was not detected"', () => {
+  const bad = JSON.stringify({
+    SchemaVersion: 2,
+    Metadata: {OS: {}},
+    Results: [{Class: 'os-pkgs', Vulnerabilities: []}],
+  });
+  assert.throws(() => parseReport(bad), /scanner error: image OS was not detected/);
+});
+
+test('a clean os-pkgs result parses even when it omits Vulnerabilities entirely', () => {
+  const clean = JSON.stringify({
+    SchemaVersion: 2,
+    Metadata: {OS: {Family: 'debian', Name: '13.1'}},
+    Results: [{Target: 'rootfs', Class: 'os-pkgs', Type: 'debian'}],
+  });
+  const parsed = parseReport(clean);
+  assert.equal(parsed.Metadata.OS.Family, 'debian');
+});
+
+// --- renderSummary: nothing dropped ---------------------------------------------------------
+
+test('renderSummary includes every finding id across all buckets, and the counts', () => {
+  const result = {
+    blocking: [{id: 'CVE-BLOCK', package: 'openssl', installed: '1.0.0', fixed: '1.0.1', severity: 'HIGH'}],
+    excepted: [
+      {id: 'CVE-EXCEPT', package: 'curl', installed: '7.0', fixed: '7.1', severity: 'CRITICAL', expires: '2026-11-01'},
+    ],
+    expiredExceptions: ['CVE-EXPIRED'],
+    reportedUnfixed: [{id: 'CVE-UNFIXED', package: 'zlib', installed: '1.2', fixed: '', severity: 'CRITICAL'}],
+    reportedOther: [{id: 'CVE-OTHER', package: 'bash', installed: '5.0', fixed: '5.1', severity: 'MEDIUM'}],
+    ignoredNonOs: [{id: 'CVE-LANG', package: 'requests', installed: '2.0', fixed: '2.1', severity: 'CRITICAL'}],
+  };
+  const summary = renderSummary(result, {today: TODAY, trivyVersion: '0.69.0'});
+  for (const id of ['CVE-BLOCK', 'CVE-EXCEPT', 'CVE-EXPIRED', 'CVE-UNFIXED', 'CVE-OTHER', 'CVE-LANG']) {
+    assert.ok(summary.includes(id), `summary is missing finding id ${id}`);
+  }
+  assert.match(summary, /OS-package scan/);
+  assert.match(summary, /blocking.*1/i);
+  assert.match(summary, /Policy: docs\/os-scan-policy\.md/);
+});
+
+// --- runCli: exit codes and injectable IO ---------------------------------------------------
+
+function fakeIo({reportText, exceptionsText}) {
+  const summaries = [];
+  const stderrLines = [];
+  return {
+    io: {
+      readFile: p => (p === 'report.json' ? reportText : exceptionsText),
+      writeSummary: (p, content) => summaries.push({path: p, content}),
+      stderr: msg => stderrLines.push(msg),
+    },
+    summaries,
+    stderrLines,
+  };
+}
+
+test('runCli exits 1 with "blocking" in stderr when blocking is non-empty', () => {
+  const reportText = JSON.stringify(report({vulns: [vuln({Severity: 'HIGH', FixedVersion: '1.0.1'})]}));
+  const exceptionsText = JSON.stringify(exceptionsFile([]));
+  const {io, stderrLines, summaries} = fakeIo({reportText, exceptionsText});
+  const code = runCli(['--report', 'report.json', '--exceptions', 'exceptions.json', '--today', TODAY], io);
+  assert.equal(code, 1);
+  assert.ok(stderrLines.some(l => l.includes('blocking')));
+  assert.equal(summaries.length, 1, 'summary must still be written on a blocked run');
+});
+
+test('runCli exits 0 when only reported (non-blocking) findings exist', () => {
+  const reportText = JSON.stringify(report({vulns: [vuln({Severity: 'MEDIUM', FixedVersion: '1.0.1'})]}));
+  const exceptionsText = JSON.stringify(exceptionsFile([]));
+  const {io} = fakeIo({reportText, exceptionsText});
+  const code = runCli(['--report', 'report.json', '--exceptions', 'exceptions.json', '--today', TODAY], io);
+  assert.equal(code, 0);
+});
+
+test('runCli exits 1 for a scanner error (fails closed)', () => {
+  const {io} = fakeIo({reportText: 'not json at all', exceptionsText: JSON.stringify(exceptionsFile([]))});
+  const code = runCli(['--report', 'report.json', '--exceptions', 'exceptions.json', '--today', TODAY], io);
+  assert.equal(code, 1);
+});
+
+test('runCli exits 1 for an invalid exceptions file (fails closed)', () => {
+  const reportText = JSON.stringify(report({vulns: [vuln({Severity: 'MEDIUM'})]}));
+  const {io} = fakeIo({reportText, exceptionsText: JSON.stringify({schema: 2, exceptions: []})});
+  const code = runCli(['--report', 'report.json', '--exceptions', 'exceptions.json', '--today', TODAY], io);
+  assert.equal(code, 1);
+});
