def _require_base_on_main(run: ReviewRun, command_runner: CommandRunner) -> None:
    """Require --base to already be on this checkout's origin/main.

    Applies to both the PR and local-checkpoint forms, so the base-commit
    grader Task 2 may materialize (``materialize_grader(grader_ref=run.base,
    ...)``) is always code that already landed on this repository's main,
    never a PR-supplied base (checker B13). No fetch happens here; a stale
    local origin/main is the operator's to refresh.
    """
    try:
        result = command_runner(
            ["git", "merge-base", "--is-ancestor", run.base, "refs/remotes/origin/main"],
            cwd=HARNESS_ROOT,
            check=False,
        )
    except OSError as exc:
        raise RunnerError(f"could not verify trust: git merge-base could not run ({type(exc).__name__})") from exc
    if result.returncode != 0:
        raise RunnerError(
            f"base is not on origin/main: {run.base[:12]} is not an ancestor of refs/remotes/origin/main;"
            " run `git fetch origin main` and retry"
        )


_GH_PR_VIEW_FIELDS = "author,isCrossRepository,headRefOid,baseRefOid"


def _pr_merge_base(pr_base: str, head: str, command_runner: CommandRunner) -> str:
    """Return ``git merge-base <pr_base> <head>``, failing closed on any error."""
    try:
        result = command_runner(
            ["git", "merge-base", pr_base, head],
            cwd=HARNESS_ROOT,
            stdout=subprocess.PIPE,
            text=True,
            check=False,
        )
    except OSError as exc:
        raise RunnerError(f"could not verify trust: git merge-base could not run ({type(exc).__name__})") from exc
    merge_base = (result.stdout or "").strip()
    if result.returncode != 0 or not _SHA_RE.fullmatch(merge_base):
        raise RunnerError(
            f"could not verify trust: no merge-base of PR base {pr_base[:12]} and head {head[:12]};"
            " run `git fetch origin` and retry"
        )
    return merge_base


def _verify_trust_pr(run: ReviewRun, command_runner: CommandRunner, match: re.Match[str]) -> dict[str, object]:
    slug, number = match.group(1), match.group(2)
    if slug != REPO_SLUG:
        raise RunnerError(f"PR URL is for a different repository: {slug!r} is not this repository ({REPO_SLUG})")
    try:
        result = command_runner(
            ["gh", "pr", "view", number, "--repo", REPO_SLUG, "--json", _GH_PR_VIEW_FIELDS],
            stdout=subprocess.PIPE,
            text=True,
            check=False,
        )
    except OSError as exc:
        raise RunnerError(f"could not verify trust: gh pr view could not run ({type(exc).__name__})") from exc
    if result.returncode != 0:
        raise RunnerError(f"could not verify trust: gh pr view exited {result.returncode}")
    try:
        data = json.loads(result.stdout or "")
    except ValueError as exc:
        raise RunnerError(
            f"could not verify trust: gh pr view returned unparseable JSON ({type(exc).__name__})"
        ) from exc
    author = data.get("author") or {}
    login = author.get("login", "")
    is_bot = bool(author.get("is_bot")) or login.endswith("[bot]")
    if data.get("isCrossRepository"):
        raise RunnerError(f"PR #{number} is cross-repository (fork): not a trusted origin for local test execution")
    if is_bot:
        raise RunnerError(
            f"not a trusted origin for local test execution: author {login} is a bot; use --untrusted for this head"
        )
    if login not in TRUSTED_AUTHORS:
        raise RunnerError(f"author {login} is not in TRUSTED_AUTHORS")
    if data.get("headRefOid") != run.head:
        raise RunnerError(f"PR head is {data.get('headRefOid')}, not --head {run.head}")
    pr_base = data.get("baseRefOid")
    if not isinstance(pr_base, str) or not _SHA_RE.fullmatch(pr_base):
        raise RunnerError(f"could not verify trust: gh pr view returned no valid baseRefOid ({pr_base!r})")
    # The reviewed base is the merge-base of the PR base and the head, the same
    # rule acceptance-readiness.cjs applies to meta.base. It equals the PR base
    # while the branch is up to date with it, and stays the branch's fork point
    # after main moves on, so the base..head diff never includes main-only
    # changes in reverse.
    reviewed_base = _pr_merge_base(pr_base, run.head, command_runner)
    if reviewed_base != run.base:
        raise RunnerError(
            f"--base {run.base} is not the reviewed base: the merge-base of PR base {pr_base} and head"
            f" {run.head} is {reviewed_base}; pass that merge-base as --base"
        )
    _require_base_on_main(run, command_runner)
    return {"method": "gh pr view", "pr_number": int(number), "author": login, "commits_checked": None}


def _verify_trust_local(run: ReviewRun, command_runner: CommandRunner) -> dict[str, object]:
    try:
        ancestor = command_runner(
            ["git", "merge-base", "--is-ancestor", run.base, run.head], cwd=HARNESS_ROOT, check=False
        )
    except OSError as exc:
        raise RunnerError(f"could not verify trust: git merge-base could not run ({type(exc).__name__})") from exc
    if ancestor.returncode != 0:
        raise RunnerError(f"base is not an ancestor of head: {run.base[:12]} is not an ancestor of {run.head[:12]}")

    try:
        contains = command_runner(
            ["git", "for-each-ref", "--contains", run.head, "--format=%(refname)", "refs/heads/"],
            cwd=HARNESS_ROOT,
            stdout=subprocess.PIPE,
            text=True,
            check=False,
        )
    except OSError as exc:
        raise RunnerError(f"could not verify trust: git for-each-ref could not run ({type(exc).__name__})") from exc

// Simulates which required jobs would run for a given change
// {files, labels, title}. Path filters make a required job skippable when
// the change's files don't trigger it (paths: no match / paths-ignore: all
// match); any job-level if: other than none (and the aggregate's always())
// conservatively marks the job skippable for every change, since a
// condition the simulator cannot evaluate is treated as a possible skip.
function requiredJobsFor({workflowText, aggregateJobId = 'ci-ready', change}) {
  const jobs = parseJobs(workflowText);
  const requiredJobIds = resolveRequiredJobIds(jobs, aggregateJobId);
  const files = (change && change.files) || [];
  const skippable = new Set();

  const onBlock = parseOnBlock(workflowText);
  if (!onBlock.syntaxError) {
    for (const data of Object.values(onBlock.triggers)) {
      if (data.paths !== undefined) {
        const patterns = parseFlowList(data.paths);
        const anyMatch = files.some(file => patterns.some(pattern => globMatch(pattern, file)));
        if (!anyMatch) {
          requiredJobIds.forEach(id => skippable.add(id));
        }
      }
      if (data['paths-ignore'] !== undefined) {
        const patterns = parseFlowList(data['paths-ignore']);
        const allIgnored = files.length > 0 && files.every(file => patterns.some(pattern => globMatch(pattern, file)));
        if (allIgnored) {
          requiredJobIds.forEach(id => skippable.add(id));
        }
      }
    }
  }

  for (const id of requiredJobIds) {
    if (aggregateJobId !== null && id === aggregateJobId) continue;
    const jobIf = extractJobIf(workflowText, id);
    if (jobIf !== null) {
      skippable.add(id);
    }
  }

  return {runs: requiredJobIds, skippable: [...skippable]};
}

// A conservative simulator (used only to demonstrate the escape in tests):
// could the aggregate job conclude success although every job in
// failedNeeds actually failed? True when the aggregate (or any of its
// steps) sets continue-on-error, or when its needs don't even cover every
// failedNeeds job. False for the real ci-ready, whose validation step fails
// closed on any non-success result.
function aggregateCanPassWith({workflowText, aggregateJobId, failedNeeds}) {
  const jobs = parseJobs(workflowText);
  const aggregateJob = jobs.find(job => job.id === aggregateJobId);
  if (!aggregateJob) {
    throw new Error(`Aggregate job "${aggregateJobId}" not found`);
  }

  const needs = aggregateJob.needs || [];
  if (failedNeeds.some(id => !needs.includes(id))) {
    return true;
  }

  return aggregateJob.lines.some(line => /\bcontinue-on-error\s*:/.test(line));
}

module.exports = {
  parseJobs,
  extractCiReady,
  checkJobListConsistency,
  extractJobIf,
  findSkipConditions,
  requiredJobsFor,
  aggregateCanPassWith,
  STEP_IF_ALLOWLIST,
  TRIGGER_CONTRACTS,
};

"""Behavior tests for tests/codex_report_status.py (REVIEW-03, REVIEW-04, REVIEW-06).

Every test exercises `assess_report()` and, for the CLI cases, `main()`
directly against the schema at .claude/schemas/codex-review-findings.schema.json.
No case may ever report the review as anything other than "complete" or
"incomplete" -- the contract (D-09) forbids any other status word.
"""

from __future__ import annotations

import copy
import json
from pathlib import Path

import pytest

from tests.codex_report_status import assess_report, main

H = "a" * 40  # inspected/expected head used by the valid fixture
B = "b" * 40  # inspected/expected base used by the valid fixture
WRONG_HEAD = "c" * 40
STALE_CURRENT = "d" * 40


def _finding_f001() -> dict:
    return {
        "id": "F001",
        "severity": "medium",
        "title": "Example reproduced defect",
        "file": "triggarr/example.py",
        "line_start": 10,
        "line_end": 12,
        "trigger": "Call with empty input",
        "execution_path": "handler -> validator -> crash",
        "consequence": "Unhandled exception on empty input",
        "evidence": "Traceback observed in a local run",
        "suggested_fix": "Add input validation before dereferencing",
        "reproduced": True,
        "reproduction_command": "uv run pytest tests/test_example.py::test_empty_input",
        "hypothesis": None,
    }


def _finding_f002() -> dict:
    return {
        "id": "F002",
        "severity": "low",
        "title": "Potential race condition",
        "file": "triggarr/other.py",
        "line_start": None,
        "line_end": None,
        "trigger": "Concurrent requests",
        "execution_path": "unknown -- not exercised",
        "consequence": "Possibly inconsistent state",
        "evidence": "Code inspection only",
        "suggested_fix": "Add locking around the shared write",
        "reproduced": False,
        "reproduction_command": None,
        "hypothesis": "Two concurrent writers could race on the same file",
    }


def _valid_report() -> dict:
    """A schema v2 report with every field populated, head=H, base=B."""
    return {
        "schema_version": "2",
        "inspected_head_sha": H,
        "inspected_base_sha": B,
        "pr_url": "none (local checkpoint, not pushed)",
        "scope": "tests/codex_report_status.py",
        "verdict": "findings",
        "summary": "Two findings identified.",
        "coverage": ["full diff reviewed", "tests executed"],
        "exclusions": [],
        "commands_run": [
            {"command": "uv run pytest tests/ -x -q", "exit_code": 0, "purpose": "run full test suite"},
        ],
        "findings": [_finding_f001(), _finding_f002()],
        "limitations": ["No access to production data"],
        "review_complete": True,
        "incomplete_reasons": [],
    }


def _valid_v1_report() -> dict:
    """A schema v1 report: no review_complete / incomplete_reasons fields."""
    report = _valid_report()
    report["schema_version"] = "1"
    del report["review_complete"]
    del report["incomplete_reasons"]
    return report


def _assess(report: dict, **overrides) -> object:
    """assess_report() on report, with sensible defaults for the SHA/attempt args."""
    kwargs = {
        "exit_code": 0,
        "expected_head": H,
        "expected_base": B,
        "current_head": H,
        "attempt": 1,
    }
    kwargs.update(overrides)
    return assess_report(json.dumps(report), **kwargs)


# --- Complete cases -----------------------------------------------------


def test_valid_report_is_complete() -> None:
    result = _assess(_valid_report())
    assert result.status == "complete"


def test_valid_report_reasons_empty() -> None:
    result = _assess(_valid_report())
    assert result.reasons == ()


def test_valid_report_qualified_ids() -> None:
    result = _assess(_valid_report())
    assert result.qualified_ids == (
        f"codex:{H[:12]}:a1:F001",
        f"codex:{H[:12]}:a1:F002",
    )


def test_valid_report_finding_count() -> None:
    result = _assess(_valid_report())
    assert result.finding_count == 2


def test_no_findings_is_complete() -> None:
    report = _valid_report()
    report["findings"] = []
    report["verdict"] = "no-findings"
    result = _assess(report)
    assert result.status == "complete"
    assert result.finding_count == 0
    assert result.qualified_ids == ()


# --- Missing / failed report ---------------------------------------------


def test_missing_report_none() -> None:
    result = assess_report(
        None, exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1
    )
    assert result.status == "incomplete"
    assert any("missing report" in r for r in result.reasons)


def test_missing_report_empty_string() -> None:
    result = assess_report(
        "", exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1
    )
    assert result.status == "incomplete"
    assert any("missing report" in r for r in result.reasons)


def test_missing_report_whitespace() -> None:
    result = assess_report(
        "   \n", exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1
    )
    assert result.status == "incomplete"
    assert any("missing report" in r for r in result.reasons)


def test_exit_code_timeout_incomplete() -> None:
    result = _assess(_valid_report(), exit_code=124)
    assert result.status == "incomplete"
    assert any("codex exited 124" in r for r in result.reasons)


def test_exit_code_one_incomplete() -> None:
    result = _assess(_valid_report(), exit_code=1)
    assert result.status == "incomplete"
    assert any("codex exited 1" in r for r in result.reasons)


def test_exit_code_none_incomplete() -> None:
    result = _assess(_valid_report(), exit_code=None)
    assert result.status == "incomplete"
    assert any("codex exit status unknown" in r for r in result.reasons)


def test_truncated_json_incomplete() -> None:
    text = json.dumps(_valid_report())[:-5]
    result = assess_report(
        text, exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1
    )
    assert result.status == "incomplete"
    assert any("unparseable" in r for r in result.reasons)


# bm:322afc50367d:IN-04 (owner-approved round 2): pathological JSON never
# raises and never resolves silently.
def test_deeply_nested_json_incomplete_without_raising() -> None:
    text = "[" * 100_000 + "]" * 100_000
    result = assess_report(text, exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1)
    assert result.status == "incomplete"
    assert "unparseable: report is nested too deeply" in result.reasons


def test_duplicate_key_json_incomplete() -> None:
    text = json.dumps(_valid_report())
    text = text[:-1] + ', "review_complete": false}'
    result = assess_report(text, exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1)
    assert result.status == "incomplete"
    assert "unparseable: duplicate key review_complete" in result.reasons


def test_nested_duplicate_key_json_incomplete() -> None:
    text = json.dumps(_valid_report()).replace('"id": "F001"', '"id": "F001", "id": "F009"', 1)
    result = assess_report(text, exit_code=0, expected_head=H, expected_base=B, current_head=H, attempt=1)
    assert result.status == "incomplete"
    assert "unparseable: duplicate key id" in result.reasons


const {test} = require('node:test');
const assert = require('node:assert/strict');
const crypto = require('node:crypto');
const {
  buildProvenance,
  buildLocalProvenance,
  checkEvidence,
  MEASURED_PATHS,
  runCli,
} = require('./coverage-provenance.cjs');

function sha256(text) {
  return crypto.createHash('sha256').update(text, 'utf8').digest('hex');
}

const HEAD_SHA = '1'.repeat(40);
const BASE_SHA = '2'.repeat(40);
const MERGE_SHA = '3'.repeat(40);
const PUSH_SHA = '4'.repeat(40);
const LOCAL_SHA = '5'.repeat(40);
const OTHER_SHA = '6'.repeat(40);
const RUN_ID = '987654321';

const WITH_BRANCHES =
  '<?xml version="1.0"?>\n<coverage line-rate="0.5" branch-rate="0.1" branches-valid="10" branches-covered="2"></coverage>\n';
const NO_BRANCHES =
  '<?xml version="1.0"?>\n<coverage line-rate="0.5" branch-rate="0" branches-valid="0" branches-covered="0"></coverage>\n';
const NO_BRANCH_ATTR = '<?xml version="1.0"?>\n<coverage line-rate="0.5"></coverage>\n';

const MEASURED_TREES = {
  triggarr: 'a'.repeat(40),
  tests: 'b'.repeat(40),
  'pyproject.toml': 'c'.repeat(40),
  'uv.lock': 'd'.repeat(40),
};

const PR_ENV = {
  GITHUB_EVENT_NAME: 'pull_request',
  GITHUB_SHA: MERGE_SHA,
  GITHUB_RUN_ID: RUN_ID,
  GITHUB_RUN_ATTEMPT: '1',
  GITHUB_WORKFLOW: 'CI',
  GITHUB_REPOSITORY: 'thejuran/triggarr',
  PR_HEAD_SHA: HEAD_SHA,
  PR_BASE_SHA: BASE_SHA,
};

const PUSH_ENV = {
  GITHUB_EVENT_NAME: 'push',
  GITHUB_SHA: PUSH_SHA,
  GITHUB_RUN_ID: RUN_ID,
  GITHUB_RUN_ATTEMPT: '1',
  GITHUB_WORKFLOW: 'CI',
  GITHUB_REPOSITORY: 'thejuran/triggarr',
};

function prProvenance({testExit = 0, coverageText = WITH_BRANCHES} = {}) {
  return buildProvenance(PR_ENV, {coverageText, testExit, testSeconds: 90, measuredTrees: MEASURED_TREES});
}

function pushProvenance({testExit = 0, coverageText = WITH_BRANCHES} = {}) {
  return buildProvenance(PUSH_ENV, {coverageText, testExit, testSeconds: 10, measuredTrees: MEASURED_TREES});
}

function localProvenanceFixture({testExit = 0} = {}) {
  return buildLocalProvenance({head: LOCAL_SHA, coverageText: WITH_BRANCHES, testExit, testSeconds: 5, measuredTrees: MEASURED_TREES});
}

// ---- buildProvenance ----

test('buildProvenance for pull_request event returns pull-request-synthetic-merge kind bound to the PR head', () => {
  const provenance = buildProvenance(PR_ENV, {
    coverageText: WITH_BRANCHES,
    testExit: 0,
    testSeconds: 90,
    measuredTrees: MEASURED_TREES,
    now: () => new Date('2026-10-27T00:00:00Z'),
  });
  assert.equal(provenance.schema, 1);
  assert.equal(provenance.event_name, 'pull_request');
  assert.equal(provenance.tested_sha_kind, 'pull-request-synthetic-merge');
  assert.equal(provenance.pr_head_sha, HEAD_SHA);
  assert.equal(provenance.pr_base_sha, BASE_SHA);
  assert.equal(provenance.tested_sha, MERGE_SHA);
  assert.equal(provenance.coverage_sha256, sha256(WITH_BRANCHES));
  assert.equal(provenance.branch_coverage, true);
  assert.deepEqual(provenance.measured_trees, MEASURED_TREES);
});

test('buildProvenance for push event has a null pr_head_sha and push-head kind', () => {
  const provenance = buildProvenance(PUSH_ENV, {
    coverageText: WITH_BRANCHES,
    testExit: 0,
    testSeconds: 42,
    measuredTrees: MEASURED_TREES,
  });
  assert.equal(provenance.pr_head_sha, null);
  assert.equal(provenance.pr_base_sha, null);
  assert.equal(provenance.tested_sha_kind, 'push-head');
  assert.equal(provenance.tested_sha, PUSH_SHA);
});

test('buildProvenance throws when GITHUB_SHA is missing', () => {
  assert.throws(
    () =>
      buildProvenance(
        {GITHUB_EVENT_NAME: 'push', GITHUB_RUN_ID: RUN_ID},
        {coverageText: WITH_BRANCHES, testExit: 0, testSeconds: 1, measuredTrees: MEASURED_TREES}
      ),
    /GITHUB_SHA/
  );
});

test('buildProvenance throws when GITHUB_RUN_ID is missing', () => {
  assert.throws(
    () =>
      buildProvenance(
        {GITHUB_EVENT_NAME: 'push', GITHUB_SHA: PUSH_SHA},
        {coverageText: WITH_BRANCHES, testExit: 0, testSeconds: 1, measuredTrees: MEASURED_TREES}
      ),
    /GITHUB_RUN_ID/
  );
});

test('buildProvenance throws when GITHUB_SHA is not 40 hex', () => {
  assert.throws(
    () =>
      buildProvenance(
        {GITHUB_EVENT_NAME: 'push', GITHUB_SHA: 'not-a-sha', GITHUB_RUN_ID: RUN_ID},
        {coverageText: WITH_BRANCHES, testExit: 0, testSeconds: 1, measuredTrees: MEASURED_TREES}
      ),
    /40-hex/
  );
});

test('buildProvenance throws when measuredTrees is missing a MEASURED_PATHS entry', () => {
  const incomplete = {...MEASURED_TREES};
  delete incomplete['uv.lock'];
  assert.throws(
    () => buildProvenance(PUSH_ENV, {coverageText: WITH_BRANCHES, testExit: 0, testSeconds: 1, measuredTrees: incomplete}),
    /uv\.lock/
  );
});

// ---- buildLocalProvenance ----

test('buildLocalProvenance returns local-exact-head kind bound to the given head', () => {
  const provenance = buildLocalProvenance({
    head: LOCAL_SHA,
    coverageText: WITH_BRANCHES,
    testExit: 0,
    testSeconds: 12,
    measuredTrees: MEASURED_TREES,
  });
  assert.equal(provenance.event_name, 'local');
  assert.equal(provenance.tested_sha_kind, 'local-exact-head');
  assert.equal(provenance.tested_sha, LOCAL_SHA);
  assert.equal(provenance.pr_head_sha, null);
  assert.equal(provenance.pr_base_sha, null);
  assert.equal(provenance.run_id, null);
name: Release

on:
  workflow_run:
    workflows: [CI]
    types: [completed]
    branches: [main]
  push:
    tags: ['v*']

permissions:
  contents: read

jobs:
  preflight:
    runs-on: ubuntu-latest
    timeout-minutes: 5
    # Skip untrusted or unsuccessful triggers so failed/cancelled CI does not
    # produce failed Release runs; release-policy.cjs still re-verifies independently.
    if: >-
      (github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')) ||
      (github.event_name == 'workflow_run' &&
       github.event.workflow_run.conclusion == 'success' &&
       github.event.workflow_run.event == 'push' &&
       github.event.workflow_run.head_branch == 'main' &&
       github.event.workflow_run.head_repository.full_name == github.repository)
    permissions:
      contents: read
      actions: read
    outputs:
      sha: ${{ steps.policy.outputs.sha }}
    steps:
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          ref: main
          persist-credentials: false
          sparse-checkout: .github/scripts
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
        id: policy
        with:
          script: |
            const {preflight} = require('./.github/scripts/release-policy.cjs');
            await preflight({github, context, core});

  release:
    concurrency:
      group: publish-${{ github.event_name == 'push' && github.ref || 'main' }}
      cancel-in-progress: false
    needs: preflight
    timeout-minutes: 30
    # Run on release tags directly, or after same-repo push CI succeeds on main.
    if: >-
      (github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')) ||
      (github.event_name == 'workflow_run' &&
       github.event.workflow_run.conclusion == 'success' &&
       github.event.workflow_run.event == 'push' &&
       github.event.workflow_run.head_branch == 'main' &&
       github.event.workflow_run.head_repository.full_name == github.repository)
    runs-on: ubuntu-latest

    permissions:
      packages: write
      contents: read
      actions: read

    steps:
      # A valid run can become stale while waiting for the publishing queue.
      - uses: actions/checkout@d23441a48e516b6c34aea4fa41551a30e30af803 # v6
        with:
          ref: main
          persist-credentials: false
          sparse-checkout: .github/scripts
      - uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
        id: recheck
        with:
          script: |
            const {preflight} = require('./.github/scripts/release-policy.cjs');
            await preflight({github, context, core});
      - name: Validate release tag format
        if: github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
        with:
          script: |
            const {parseReleaseTag} = require('./.github/scripts/release-policy.cjs');
            const version = parseReleaseTag(context.ref);
            core.info(`Release tag format accepted: ${version}`);
      - name: Download exact successful CI image
        uses: actions/download-artifact@d3f86a106a0bac45b974a628896c90dbdf5c8093 # v4
        with:
          name: audited-image
          path: image
          run-id: ${{ steps.recheck.outputs.run_id }}
          github-token: ${{ secrets.GITHUB_TOKEN }}
      - name: Verify and load audited image
        working-directory: image
        run: |
          sha256sum -c image.tar.sha256
          docker load -i image.tar
          test "$(docker image inspect triggarr:ci-test --format '{{.Id}}')" = "$(cat image-id.txt)"
      - name: Read audited image version label
        if: github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')
        id: image-version
        run: |
          version="$(docker image inspect triggarr:ci-test --format '{{ index .Config.Labels "org.opencontainers.image.version" }}')"
          if ! [[ "$version" =~ ^[A-Za-z0-9.+_-]*$ ]]; then
            echo "Release rejected: image version label contains unexpected characters" >&2
            exit 1
          fi
          echo "version=$version" >> "$GITHUB_OUTPUT"
      - name: Verify release version identity
        if: github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')
        uses: actions/github-script@ed597411d8f924073f98dfc5c65a23a2325f34cd # v8
        env:
          IMAGE_VERSION: ${{ steps.image-version.outputs.version }}
          RELEASE_SHA: ${{ steps.recheck.outputs.sha }}
        with:
          script: |
            const {releaseIdentityGate} = require('./.github/scripts/release-policy.cjs');
            await releaseIdentityGate({github, context, core, sha: process.env.RELEASE_SHA, imageVersion: process.env.IMAGE_VERSION});

      - uses: docker/login-action@dbcb813823bdd20940b903addbd779551569679f # v4
        with:
          registry: ghcr.io
          username: ${{ github.actor }}
          password: ${{ secrets.GITHUB_TOKEN }}

      - name: Detect Docker Hub mirror
        id: dockerhub
        env:
          DOCKERHUB_USERNAME: ${{ vars.DOCKERHUB_USERNAME }}
          DOCKERHUB_TOKEN: ${{ secrets.DOCKERHUB_TOKEN }}
        run: |
          if [ -n "$DOCKERHUB_USERNAME" ] && [ -n "$DOCKERHUB_TOKEN" ]; then
            echo "enabled=true" >> "$GITHUB_OUTPUT"
            echo "image=${DOCKERHUB_USERNAME}/triggarr" >> "$GITHUB_OUTPUT"
          else
            echo "enabled=false" >> "$GITHUB_OUTPUT"
            echo "image=" >> "$GITHUB_OUTPUT"
          fi

      - name: Login to Docker Hub
        if: steps.dockerhub.outputs.enabled == 'true'
        uses: docker/login-action@dbcb813823bdd20940b903addbd779551569679f # v4
        with:
          username: ${{ vars.DOCKERHUB_USERNAME }}
          password: ${{ secrets.DOCKERHUB_TOKEN }}

      - name: Extract metadata
        id: meta
        uses: docker/metadata-action@dc802804100637a589fabce1cb79ff13a1411302 # v6
        with:
          images: |
            ghcr.io/thejuran/triggarr
            ${{ steps.dockerhub.outputs.image }}
          tags: |
            type=raw,value=main,enable=${{ github.event_name == 'workflow_run' }}
            type=raw,value=dev,enable=${{ github.event_name == 'workflow_run' }}
            type=raw,value=latest,enable=${{ startsWith(github.ref, 'refs/tags/v') }}
            type=ref,event=tag

      - name: Publish audited image without rebuilding
        env:
          IMAGE_TAGS: ${{ steps.meta.outputs.tags }}
        run: |
          while IFS= read -r target; do
            [ -n "$target" ] || continue
            docker tag triggarr:ci-test "$target"
            docker push "$target"
          done <<< "$IMAGE_TAGS"

  # Only this tag-only job holds contents: write (CIMAINT-07). Python
  # distributions are no longer attached to releases (D-14); earlier
  # releases keep theirs.
  github-release:
    needs: [preflight, release]
    if: github.event_name == 'push' && startsWith(github.ref, 'refs/tags/v')
    runs-on: ubuntu-latest
    timeout-minutes: 5
    concurrency:
      group: github-release-${{ github.ref }}
      cancel-in-progress: false

    permissions:
      contents: write

    steps:
      - name: Create GitHub Release
        env:
          GH_TOKEN: ${{ secrets.GITHUB_TOKEN }}
          GH_REPO: ${{ github.repository }}
          TAG_NAME: ${{ github.ref_name }}
        run: |
          if gh release view "$TAG_NAME" &>/dev/null; then
            echo "Release $TAG_NAME already exists"
          else
            gh release create "$TAG_NAME" \
              --title "Triggarr $TAG_NAME" \
              --generate-notes \
              --latest
          fi

